    /// <summary>
    /// Update Filename and subject in SrsReportRunMailer object
    /// </summary>
    /// <param name = "_kpmgSRSReportRunMailer">Type SrsReportRunMailer</param>
    private void kpmgUpdateSrsReportRunMailerForFreeTextInvoice(SrsReportRunMailer    _kpmgSRSReportRunMailer)
    {

        FreeTextInvoiceContract             kpmgFreeTextInvoiceContract = reportContract.parmRdpContract() as FreeTextInvoiceContract;
        CustInvoiceJour                     kpmgCustInvoiceJour         = CustInvoiceJour::findRecId(kpmgFreeTextInvoiceContract.parmCustInvoiceJourRecId());
        CustAccount                         kpmgCustAccount             = kpmgCustInvoiceJour.InvoiceAccount;
        Filename                            kpmgFileName                = _kpmgSRSReportRunMailer.parmKPMGFileName();
        SysEmailSubject                     kpmgEmailSubject            = _kpmgSRSReportRunMailer.parmKPMGSysEmailSubject();
        
        if(kpmgFileName)
        {
            kpmgFileName        = strReplace(kpmgFileName, '%AccountNum%', strRFix(kpmgCustAccount, 10, '0'));
            kpmgFileName        = strReplace(kpmgFileName, '%Pillar%', METHelper::getDimensionValue(CustTable::find(kpmgCustAccount).DefaultDimension, METConstants::pillar));
            kpmgFileName        = strReplace(kpmgFileName, '%InvoiceNum%', kpmgCustInvoiceJour.InvoiceId);
            _kpmgSRSReportRunMailer.parmKPMGFileName(kpmgFileName);
        }
        if(kpmgEmailSubject)
        {
            kpmgEmailSubject    = strReplace(kpmgEmailSubject, '%AccountNum%', kpmgCustAccount);
            kpmgEmailSubject    = strReplace(kpmgEmailSubject, '%CustomerName%', CustTable::find(kpmgCustAccount).name());
            _kpmgSRSReportRunMailer.parmKPMGSysEmailSubject(kpmgEmailSubject);
        }
    }

    /// <summary>
    /// Update Filename and subject in SrsReportRunMailer object
    /// </summary>
    /// <param name = "_kpmgSRSReportRunMailer">Type SrsReportRunMailer</param>
    private void kpmgUpdateSrsReportRunMailerForMETCustInterestNote(SrsReportRunMailer    _kpmgSRSReportRunMailer)
    {

        CustInterestNoteContract            kpmgCustInterestNoteContract    = reportContract.parmRdpContract() as CustInterestNoteContract;
        CustInterestJour                    kpmgCustInterestJour            = CustInterestJour::findRecId(kpmgCustInterestNoteContract.parmRecordId());
        CustAccount                         kpmgCustAccount                 = kpmgCustInterestJour.AccountNum;
        Filename                            kpmgFileName                    = _kpmgSRSReportRunMailer.parmKPMGFileName();
        SysEmailSubject                     kpmgEmailSubject                = _kpmgSRSReportRunMailer.parmKPMGSysEmailSubject();
        
        if(kpmgFileName)
        {
            kpmgFileName        = strReplace(kpmgFileName, '%AccountNum%', strRFix(kpmgCustAccount, 10, '0'));
            kpmgFileName        = strReplace(kpmgFileName, '%Pillar%', METHelper::getDimensionValue(CustTable::find(kpmgCustAccount).DefaultDimension, METConstants::pillar));
            kpmgFileName        = strReplace(kpmgFileName, '%InvoiceNum%', kpmgCustInterestJour.InterestNote);
            _kpmgSRSReportRunMailer.parmKPMGFileName(kpmgFileName);
        }
        if(kpmgEmailSubject)
        {
            kpmgEmailSubject    = strReplace(kpmgEmailSubject, '%AccountNum%', kpmgCustAccount);
            kpmgEmailSubject    = strReplace(kpmgEmailSubject, '%CustomerName%', CustTable::find(kpmgCustAccount).name());
            _kpmgSRSReportRunMailer.parmKPMGSysEmailSubject(kpmgEmailSubject);
        }
    }

    /// <summary>
    /// Update Filename and subject in SrsReportRunMailer object
    /// </summary>
    /// <param name = "_kpmgSRSReportRunMailer">Type SrsReportRunMailer</param>
    private void kpmgUpdateSrsReportRunMailerForCustCollection(SrsReportRunMailer    _kpmgSRSReportRunMailer)
    {

        CustCollectionJourContract          kpmgCustCollectionJourContract  = reportContract.parmRdpContract() as CustCollectionJourContract;
        custCollectionLetterJour            kpmgcustCollectionLetterJour    = custCollectionLetterJour::findRecId(kpmgCustCollectionJourContract.parmRecordId());
        CustAccount                         kpmgCustAccount                 = kpmgcustCollectionLetterJour.AccountNum;
        Filename                            kpmgFileName                    = _kpmgSRSReportRunMailer.parmKPMGFileName();
        SysEmailSubject                     kpmgEmailSubject                = _kpmgSRSReportRunMailer.parmKPMGSysEmailSubject();
        
        if(kpmgFileName)
        {
            kpmgFileName        = strReplace(kpmgFileName, '%AccountNum%', strRFix(kpmgCustAccount, 10, '0'));
            if(strContains(kpmgFileName, '%Pillar%'))
            {
                kpmgFileName        = strReplace(kpmgFileName, '%Pillar%', METHelper::getDimensionValue(CustTable::find(kpmgCustAccount).DefaultDimension, METConstants::pillar));
            }
            _kpmgSRSReportRunMailer.parmKPMGFileName(kpmgFileName);
        }
        if(kpmgEmailSubject)
        {
            kpmgEmailSubject    = strReplace(kpmgEmailSubject, '%AccountNum%', kpmgCustAccount);
            kpmgEmailSubject    = strReplace(kpmgEmailSubject, '%CustomerName%', CustTable::find(kpmgCustAccount).name());
            _kpmgSRSReportRunMailer.parmKPMGSysEmailSubject(kpmgEmailSubject);
        }
    }

    /// <summary>
    /// Update Filename and subject in SrsReportRunMailer object
    /// </summary>
    /// <param name = "_kpmgSRSReportRunMailer">Type SrsReportRunMailer</param>
    private void kpmgUpdateSrsReportRunMailerForPurchaseOrder(SrsReportRunMailer    _kpmgSRSReportRunMailer)
    {

        PurchPurchaseOrderContract          kpmgPurchPurchaseOrderContract  = reportContract.parmRdpContract() as PurchPurchaseOrderContract;
        PurchTable                          kpmgPurchTable                  = PurchTable::findRecId(kpmgPurchPurchaseOrderContract.parmRecordId());
        VendAccount                         kpmgVendAccount                 = kpmgPurchTable.InvoiceAccount;
        Filename                            kpmgFileName                    = _kpmgSRSReportRunMailer.parmKPMGFileName();
        SysEmailSubject                     kpmgEmailSubject                = _kpmgSRSReportRunMailer.parmKPMGSysEmailSubject();
        
        if(kpmgFileName)
        {
            kpmgFileName        = strReplace(kpmgFileName, '%AccountNum%', kpmgVendAccount);
            kpmgFileName        = strReplace(kpmgFileName, '%PurchId%', kpmgPurchTable.PurchId);
            _kpmgSRSReportRunMailer.parmKPMGFileName(kpmgFileName);
        }
        if(kpmgEmailSubject)
        {
            kpmgEmailSubject    = strReplace(kpmgEmailSubject, '%AccountNum%', kpmgVendAccount);
            kpmgEmailSubject    = strReplace(kpmgEmailSubject, '%VendorName%', kpmgPurchTable.invoiceName());
            _kpmgSRSReportRunMailer.parmKPMGSysEmailSubject(kpmgEmailSubject);
        }
    }
